3	function trackConsoleErrors(page: Page): string[] {
4	  const errors: string[] = [];
5	  page.on('console', (message) => {
6	    if (message.type() === 'error') errors.push(message.text());
7	  });
8	  page.on('pageerror', (error) => {
9	    errors.push(error.message);
10	  });
11	  return errors;
12	}
