143	test('practice page shows UA fallback when LexiconPractice island chunk fails to load (#4694)', async ({ page }) => {
144	  // Route-abort the island's dynamic chunk (identified by stem in filename, stable across
145	  // builds) to simulate the exact astro-island pre-React failure mode:
146	  // "Failed to fetch dynamically imported module". This fires the 'astro:hydration-error'
147	  // event (and/or watchdog) before any React code or its error boundary can run.
148	  //
149	  // Astro 7.1+ retries a failed island import once with `?astro-retry=<ts>` after 1s
150	  // (importWithRetry). A glob ending in `.js` misses that retry URL and the island
151	  // hydrates successfully — match on the LexiconPractice stem with or without query.
152	  await page.route(/LexiconPractice[^/]*\.js(?:\?|$)/, (route) => route.abort());
153	
154	  await page.goto('/words-of-the-day/practice/');
155	
156	  // Expect the static UA fallback (error listener path is fast; no reliance on 10s timeout).
157	  // Allow for Astro's 1s import retry before hydration-error fires.
158	  const fallback = page.locator('#lexicon-practice-fallback');
159	  await expect(fallback).toBeVisible({ timeout: 8000 });
160	  await expect(fallback).toContainText('Не вдалося завантажити практику');
161	  const retryBtn = page.getByRole('button', { name: 'Спробувати ще раз' });
162	  await expect(retryBtn).toBeVisible();
163	
164	  // Mount wrapper is hidden on failure; fallback is swapped in.
165	  await expect(page.locator('#lexicon-practice-mount')).toHaveAttribute('hidden', '');
166	});
