180	async function assertFirstViewportPracticeCTAs(page: Page, locale: 'en' | 'uk'): Promise<void> {
181	  const start = page.getByTestId('practice-start-session');
182	  const reset = page.locator('button[data-reset-mode="mixed"]');
183	
184	  for (const control of [start, reset]) {
185	    await expect(control).toBeVisible();
186	    const box = await control.boundingBox();
187	    expect(box).not.toBeNull();
188	    const top = box!.y;
189	    const bottom = box!.y + box!.height;
190	    expect(top).toBeGreaterThanOrEqual(0);
191	    expect(bottom).toBeLessThanOrEqual(768);
192	  }
193	
194	  // Accessible names must match the active chrome locale only (no slash duplicates).
195	  // With a resumable Mixed snapshot (D5), the primary CTA is the REAL resume action
196	  // ("Resume session" / "Продовжити заняття") and the secondary is the danger-outline
197	  // reset ("Start over" / "Почати наново").
198	  if (locale === 'en') {
199	    await expect(page.getByRole('button', { name: 'Resume session' })).toBeVisible();
200	    await expect(page.getByRole('button', { name: 'Start over' })).toBeVisible();
201	    await expect(page.getByRole('button', { name: /Start session|Почати заняття|Почати наново/ })).toHaveCount(0);
202	  } else {
203	    await expect(page.getByRole('button', { name: 'Продовжити заняття' })).toBeVisible();
204	    await expect(page.getByRole('button', { name: 'Почати наново' })).toBeVisible();
205	    await expect(page.getByRole('button', { name: /Start session|Resume session|Почати заняття/ })).toHaveCount(0);
206	  }
207	
208	  // The words disclosure begins closed and the 3D preview remains visible.
209	  const details = page.getByTestId('practice-daily-details');
210	  await expect(details).not.toHaveAttribute('open');
211	  await expect(page.locator('.flashcard.daily-preview-card')).toBeVisible();
212	
213	  // The one-column visual hierarchy is the actual DOM/tab order, not a CSS
214	  // placement trick that would make keyboard navigation disagree with the page.
215	  await expect.poll(async () =>
216	    page.locator('.k3-practice-dashboard > [data-testid]').evaluateAll(
217	      (elements) => elements.map((element) => element.getAttribute('data-testid')),
218	    ),
219	  ).toEqual([
220	    'practice-dashboard-hero',
221	    'practice-dashboard-stats',
222	    'practice-dashboard-words',
223	    'practice-dashboard-session',
224	    'practice-dashboard-secondary',
225	  ]);
226	}
