357	/** Complete one flashcard round (flip + rate) so the caller can advance or inspect progress. */
358	async function completeOneFlashcard(page: Page, rating: 'good' | 'easy' | 'hard' | 'again' = 'good'): Promise<void> {
359	  const card = page.locator('[data-activity="flashcard"]');
360	  await expect(card).toBeVisible();
361	  await card.click();
362	  await expect(card).toHaveAttribute('data-flipped', 'true');
363	  await page.locator(`[data-rate="${rating}"]`).click();
364	  await expect(page.getByTestId('practice-advance-button')).toBeVisible();
