367	/**
368	 * `Mixed` mode opens on any of the 11 exercise types (D3: session-seeded, not fixed).
369	 * Flashcards and every "pick one option" mode (choice/classify/synonym/paradigm/
370	 * paronym/heritage) share simple, quick completions; the rest (matching/cloze/
371	 * stress) are not needed here, so retry with a fresh session-seeded draw instead
372	 * of teaching this helper all 11 interaction shapes.
373	 */
374	async function completeOneEasyMixedItem(page: Page): Promise<void> {
375	  for (let attempt = 0; attempt < 8; attempt += 1) {
376	    await expect(page.locator('.lexicon-practice-stage')).toBeVisible();
377	    const flashcard = page.locator('[data-activity="flashcard"]');
378	    const mcOption = page.locator('.mc-opt').first();
379	    if (await flashcard.isVisible().catch(() => false)) {
380	      await flashcard.click();
381	      await page.locator('[data-rate="good"]').click();
382	      await expect(page.getByTestId('practice-advance-button')).toBeVisible();
383	      return;
384	    }
385	    if (await mcOption.isVisible().catch(() => false)) {
386	      await mcOption.click();
387	      await expect(page.getByTestId('practice-advance-button')).toBeVisible();
388	      return;
389	    }
390	    // Going home without completing anything leaves a resumable snapshot, so the
391	    // primary CTA would now RESUME this exact (unhandled-type) session instead of
392	    // drawing fresh — use the reset control (D5) to force a genuinely new draw.
393	    await page.getByRole('button', { name: /Додому|Home/ }).click();
394	    const reset = page.locator('button[data-reset-mode="mixed"]');
395	    if (await reset.isVisible().catch(() => false)) {
396	      await reset.click();
397	    } else {
398	      await page.getByTestId('practice-start-session').click();
399	    }
400	  }
401	  throw new Error('Could not reach an easily-completable mixed-mode item after 8 tries');
402	}
