527	/**
528	 * F1/F2 (PR #5837 review): route disjoint, single-item fixture decks for the A1/A2 core
529	 * shards so "the accepted level drives the session" is provable from ITEM CONTENT, not
530	 * merely from a request having fired for the right URL — a same-tick closure bug could
531	 * silently replay the stale level's pool while the request log still looks correct.
532	 * `depleteLowerLevel` is called right before the level switch so the (real, harmless)
533	 * background lower-level merge a higher level kicks off can never dilute the accepted
534	 * level's pool back into ambiguous territory.
535	 */
536	async function mockDisjointLevelFixtures(page: Page): Promise<{ depleteLowerLevel(level: 'A1' | 'A2'): void }> {
537	  const depleted = new Set<'A1' | 'A2'>();
538	  const fixtureItem = (level: 'A1' | 'A2') => ({
539	    lemmaId: `e2eFixture${level}`,
540	    lemma: `e2eFixture${level}`,
541	    cefr: level,
542	    modes: ['flashcards'] as const,
543	    hasCloze: false,
544	    clozeIds: [] as string[],
545	    newOrder: 0,
546	  });
547	  const fixtureLexeme = (level: 'A1' | 'A2') => ({
548	    lemmaId: `e2eFixture${level}`,
549	    lemma: `e2eFixture${level}`,
550	    lemmaPlain: `e2eFixture${level}`,
551	    ipa: null,
552	    gloss: `e2eFixture${level}`,
553	    pos: 'noun',
554	    cefr: level,
555	    heritage: null,
556	    severity: null,
557	    paradigm: { cases: {} },
558	  });
559	  for (const level of ['A1', 'A2'] as const) {
560	    await page.route(`**/lexicon/practice-index.${level}.json`, (route) =>
561	      route.fulfill({
562	        contentType: 'application/json',
563	        body: JSON.stringify({
564	          deckVersion: `e2e-fixture-${level}`,
565	          level,
566	          items: depleted.has(level) ? [] : [fixtureItem(level)],
567	        }),
568	      }),
569	    );
570	    await page.route(`**/lexicon/practice-lexemes.${level}.json`, (route) =>
571	      route.fulfill({
572	        contentType: 'application/json',
573	        body: JSON.stringify({
574	          deckVersion: `e2e-fixture-${level}`,
575	          level,
576	          lexemes: depleted.has(level) ? [] : [fixtureLexeme(level)],
577	        }),
578	      }),
579	    );
580	  }
581	  return { depleteLowerLevel: (level) => depleted.add(level) };
582	}
