/* TEMPORARY PROBE — dumps visible text nodes per surface/locale. Delete before commit. */
import { test, type Page } from '@playwright/test';

const SURFACES = ['/words-of-the-day/practice/', '/lexicon/', '/lexicon/browse/'];

async function dump(page: Page, path: string, locale: 'en' | 'uk') {
  await page.addInitScript((loc) => window.localStorage.setItem('lu-chrome-locale', loc), locale);
  await page.goto(path);
  await page.waitForLoadState('networkidle');
  await page.waitForTimeout(1500);
  const nodes = await page.evaluate(() => {
    const out: { text: string; path: string }[] = [];
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    let node = walker.nextNode();
    while (node) {
      const el = node.parentElement;
      const text = (node.textContent ?? '').replace(/\s+/g, ' ').trim();
      if (el && text && !['SCRIPT', 'STYLE', 'NOSCRIPT', 'TEMPLATE'].includes(el.tagName)) {
