          const cls = typeof el.className === 'string' && el.className ? '.' + el.className.split(' ').join('.') : '';
          out.push({ text: text.slice(0, 60), path: `${el.tagName.toLowerCase()}${cls}` });
        }
      }
      node = walker.nextNode();
    }
    return out;
  });
  console.log(`\n===== ${path} [${locale}] =====`);
  for (const n of nodes) console.log(`${n.path}  ::  ${n.text}`);
}

