/* TEMPORARY PROBE 2 — check dual-locale visibility inside React island vs Astro nav. */
import { test } from '@playwright/test';

test('probe visibility of data-loc spans', async ({ page }) => {
  await page.addInitScript(() => window.localStorage.setItem('lu-chrome-locale', 'uk'));
  await page.goto('/words-of-the-day/practice/');
  await page.waitForLoadState('networkidle');
  await page.waitForTimeout(1500);
  const report = await page.evaluate(() => {
    const htmlLocale = document.documentElement.getAttribute('data-chrome-locale');
    const rows: string[] = [`html data-chrome-locale=${htmlLocale}`];
    for (const span of Array.from(document.querySelectorAll('.lu-i18n')).slice(0, 200)) {
      const en = span.querySelector("[data-loc='en']");
      const uk = span.querySelector("[data-loc='uk']");
      if (!en || !uk) continue;
      const enVis = en.checkVisibility();
      const ukVis = uk.checkVisibility();
      if (enVis && ukVis) {
        const inIsland = !!span.closest('#lexicon-practice-mount');
        rows.push(
          `BOTH-VISIBLE island=${inIsland} key=${span.getAttribute('data-i18n')} en="${en.textContent}" uk="${uk.textContent}"`,
        );
      }
    }
    return rows;
  });
  console.log(report.join('\n'));
});

